/**
 * Claude AI content generation service.
 *
 * Mode priority:
 *   1. Claude CLI (claude -p ...) — user logged in via `claude` terminal session, no API key needed
 *   2. Anthropic SDK — if ANTHROPIC_API_KEY is set in .env
 *
 * Content is generated by combining all brand context files + generation rules + spreadsheet row data
 * into a single comprehensive prompt.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const crossSpawn = require('cross-spawn');

// Lazy-load queueService to avoid circular deps — only needed at call time
function getActiveModel() {
  try { return require('./queueService').getClaudeModel(); } catch { /* fallback */ }
  return process.env.CLAUDE_MODEL || 'claude-sonnet-4-6';
}

function getActiveEffort() {
  try { return require('./queueService').getClaudeEffort(); } catch { /* fallback */ }
  return 'high';
}

// Active generation engine: 'native' (built-in 2-call pipeline) or 'seomachine'
// (drives seomachine's methodology + Python quality gate). queue_state wins if it
// exposes the setting (UI-toggleable later); otherwise falls back to env, then 'native'.
function getActiveEngine() {
  try {
    const q = require('./queueService');
    if (typeof q.getGenerationEngine === 'function') {
      const e = q.getGenerationEngine();
      if (e) return String(e).toLowerCase();
    }
  } catch { /* fallback */ }
  return (process.env.GENERATION_ENGINE || 'native').toLowerCase();
}

// cross-spawn resolves the `claude` command to its real binary on every platform
// (on Windows the global install is a `claude.cmd`/`claude.ps1` shim that Node's
// child_process.execFile/spawn cannot launch directly — it throws ENOENT). It also
// escapes arguments safely, so user-supplied prompts cannot inject shell commands.
const spawn = crossSpawn;

/**
 * Promise wrapper around the Claude CLI that mimics the parts of execFileAsync we use.
 * Buffers stdout/stderr, supports a timeout, and rejects on non-zero exit or spawn error.
 * @returns {Promise<{stdout: string, stderr: string}>}
 */
function execClaudeAsync(args, opts = {}) {
  const { timeout, ...spawnOpts } = opts;
  return new Promise((resolve, reject) => {
    const proc = crossSpawn('claude', args, {
      env: { ...process.env, NO_COLOR: '1' },
      ...spawnOpts,
    });

    let stdout = '';
    let stderr = '';
    let settled = false;

    const finish = (fn, arg) => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      fn(arg);
    };

    // On Windows the spawned process is a `cmd.exe`/shim that forks the real
    // `claude` (node) process; proc.kill() only reaps the shim and leaves the
    // child alive (pipes stay open, 'close' never fires). taskkill /T kills the
    // whole tree. On POSIX a plain kill is sufficient.
    const killTree = () => {
      if (!proc.pid) return;
      if (process.platform === 'win32') {
        crossSpawn('taskkill', ['/pid', String(proc.pid), '/T', '/F']);
      } else {
        proc.kill('SIGKILL');
      }
    };

    const timer = timeout
      ? setTimeout(() => {
          killTree();
          finish(reject, new Error(`Claude CLI timed out after ${timeout}ms`));
        }, timeout)
      : null;

    proc.stdout?.on('data', (chunk) => { stdout += chunk.toString(); });
    proc.stderr?.on('data', (chunk) => { stderr += chunk.toString(); });

    proc.on('error', (err) => finish(reject, err));

    proc.on('close', (code) => {
      if (code === 0) return finish(resolve, { stdout, stderr });
      finish(reject, new Error(stderr.trim() || `Claude CLI exited with code ${code}`));
    });
  });
}

// Cache CLI status for 1 minute — short enough that a fresh login shows up quickly
let _cliCache = null;
let _cliCacheTime = 0;
const CLI_CACHE_TTL = 60 * 1000;

// Lazy-load the Anthropic SDK only when API key mode is needed
let _sdkClient = null;
function getSdkClient() {
  if (!_sdkClient) {
    const Anthropic = require('@anthropic-ai/sdk');
    _sdkClient = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
  }
  return _sdkClient;
}

// ─────────────────────────────────────────────────────────────
// Context & rules loading
// ─────────────────────────────────────────────────────────────

function loadContextFiles(contextPath) {
  if (!contextPath) return '';
  const absPath = path.resolve(process.cwd(), contextPath);
  if (!fs.existsSync(absPath)) return '';
  const files = fs.readdirSync(absPath).filter(f => f.endsWith('.md')).sort();
  return files.map(f => {
    const content = fs.readFileSync(path.join(absPath, f), 'utf8');
    return `### Context File: ${f}\n${content}`;
  }).join('\n\n---\n\n');
}

function loadRulesFile(rulesPath) {
  if (!rulesPath) return '';
  const absPath = path.resolve(process.cwd(), rulesPath);
  if (!fs.existsSync(absPath)) return '';
  return fs.readFileSync(absPath, 'utf8');
}

// ─────────────────────────────────────────────────────────────
// Prompt construction
// ─────────────────────────────────────────────────────────────

function buildFeedbackSection(feedbackList) {
  if (!Array.isArray(feedbackList) || !feedbackList.length) return '';
  const items = feedbackList.map((f, i) => {
    const tag = f.rating === 'down' ? ' [fix — this was a problem]'
      : f.rating === 'up' ? ' [keep doing this]' : '';
    return `${i + 1}. ${String(f.feedback).trim()}${tag}`;
  }).join('\n');
  return `## Editor Feedback — Apply These Learnings (HIGHEST PRIORITY)
The human editor reviewed previously published drafts for this blog and left the notes below. Treat them as strict, non-negotiable requirements and apply EVERY one of them to this article. If any conflict with the general rules above, the editor feedback wins.
${items}
`;
}

// Derive the brand name from a blog config row: "EveryCRED Blog" -> "EveryCRED".
function brandFromBlog(blog) {
  const raw = blog && blog.name ? String(blog.name).trim() : '';
  const name = raw.replace(/\s*blog\s*$/i, '').trim();
  return name || (blog && blog.domain) || 'this brand';
}

function buildSystemContent(contextContent, rulesContent, feedbackList = [], blog = {}) {
  const brand = brandFromBlog(blog);
  return `You are a senior content strategist and blog writer for ${brand}. You write expert-level, SEO-optimized blog articles that read like they come from a practitioner with years of real, hands-on experience — not a generic content writer.

## Writing Identity
- Write in first person as a senior practitioner at ${brand}
- Ground every claim in the real proof points, case studies, outcomes, and capabilities given in the Brand and Editorial Context below — never invent metrics, and never borrow another company's case studies or numbers
- Confident and direct — never hedge with "might", "possibly", "could potentially"
- Plain language over jargon; explain technical concepts clearly

## How to Use the Rules and Context Below
The Brand and Editorial Context and the Generation Rules that follow are AUTHORITATIVE for this specific blog. They define its brand voice, audience, word count, FAQ count, heading style, formatting, banned phrases, internal-linking sources, and structure. Wherever they specify a number or a rule, follow THEM — never substitute a generic default. If anything elsewhere in this prompt conflicts with them, the blog's rules win.

${contextContent ? `## Brand and Editorial Context\n\n${contextContent}` : ''}
${rulesContent ? `## Generation Rules\n\n${rulesContent}` : ''}
${buildFeedbackSection(feedbackList)}
## Generation Process — Follow These Phases in Order

### Phase 1 — RESEARCH
Before writing, model the SERP landscape:
- What do the top-ranking articles for this keyword all cover? What is MISSING?
- What unique angle can ${brand} own that competitors don't, based on the brand context above?
- What is the exact search intent: informational, commercial, transactional?
- What People Also Ask questions exist? Build them into H2s or FAQ.
- Where do the brand's real proof points (from the context above) add genuine evidence? Never invent or borrow numbers.
- Check the internal-links-map context file for already-published ${brand} articles on similar topics — link to them for internal linking, and do NOT write a duplicate of an article that already exists.

### Phase 2 — WRITE
Follow this exact structure:
1. **Direct answer first** (1-2 sentences): AI scrapers (ChatGPT, Perplexity, Gemini) pull from the top of the page. Answer the query IMMEDIATELY.
2. **Hook** (choose one: provocative question / surprising stat / bold statement / counterintuitive claim)
3. **APP formula**: Agree (acknowledge reader's belief) → Promise (what they'll learn) → Preview (mini-TOC for long posts)
4. **Body** (H2 sections with H3 sub-sections — use the section count and per-section length from this blog's rules): Every claim backed by logic or data. No filler.
5. **Conclusion**: Summarize key takeaways
6. **CTA**: Natural call to action relevant to ${brand}
7. **FAQ**: Use the FAQ count and answer length defined in this blog's rules

### Phase 3 — OPTIMIZE (Rank Math 80-100 checklist — satisfy EVERY item)
This is mandatory. The article is scored by Rank Math SEO; hit all of these:

**Focus keyword placement (use the EXACT primary keyword phrase, verbatim):**
- In the FIRST sentence of the article (within the first 10% of content)
- In the H1 / title
- In AT LEAST 2 of the H2 subheadings, written as the exact phrase
- Use the EXACT primary keyword phrase 8-12 times across the article (intro, at least 2 H2s, several body paragraphs, the conclusion) — Rank Math measures density on the exact phrase, so 4-6 uses scores too low; aim for ~1% without sounding stuffed
- In the image alt text
- In the URL slug
- In the SEO title and meta description

**SEO title (\`seo_title\`):** 50-60 characters. START with the primary keyword. Include ONE number (a year, count, or stat) AND ONE power word (e.g. Proven, Essential, Complete, Ultimate, Smart, Powerful). Make it positive or clearly definitive in sentiment.

**Meta description (\`meta_description\`):** 150-160 characters. Include the primary keyword within the first 120 characters. End with a soft call to action.

**URL slug (\`slug\`):** lowercase, hyphen-separated, 3-6 words, MUST contain the primary keyword, ≤ 75 characters, no stop-word padding.

**Links (required for score — DISTRIBUTE, never cluster):**
- Internal links from the internal-links-map context file (use the internal-link count from this blog's rules), each placed in a DIFFERENT section where the topic is contextually relevant — never list them all in one paragraph or at the end
- AT LEAST 1 external link to a high-authority source (e.g. a well-known industry/research/standards site), placed inline within the paragraph that cites the stat or claim it supports — not in a standalone "sources" section
- No section should contain more than 1-2 links; spread them naturally across the body

**Structure & readability:**
- Hit the word count, section count, and FAQ count defined in this blog's Generation Rules — do not pad or fall back to a generic length
- Short paragraphs (per the blog's rules), at least one bulleted or numbered list, and a "Key Takeaways" bulleted block near the top
- Schema-friendly FAQ (clean Q&A pairs)

### Phase 4 — SCRUB
Before finalizing, remove AI fingerprints and apply this blog's formatting and banned-phrase rules:
- Apply this blog's punctuation and formatting rules exactly (em dashes, heading punctuation, etc.) as defined in its Generation Rules
- Remove banned filler: "it's worth noting", "in today's landscape", "in conclusion", "delve into", "leverage", "utilize", plus any others the blog's rules ban
- Vary sentence length (mix short punchy sentences with longer explanatory ones)
- Remove any zero-width spaces or invisible Unicode characters
- Ensure no paragraph starts with "I" consecutively

## CALL-TO-ACTION (CTA) BLOCKS
Produce exactly 3 distinct CTAs that drive business and generate qualified leads for ${brand}, tailored to THIS article's topic.
- Tone: professional, expert, confident, approachable, and high-conversion (a direct sales tone that asks for the next step).
- Voice: write like a human, not AI. Use simple present tense and strong action verbs. Be concise.
- Each CTA needs: a punchy heading (≤ 60 chars), a 1-2 sentence description (≤ 160 chars) tied to the reader's outcome, and a short button label (2-5 words, action verb, e.g. "Talk to a Cloud Expert", "Get Your Free Assessment").
- The 3 CTAs must be unique (different angle/offer), not repetitive.
- Also classify the article into ONE cta_category from this exact list (pick the closest fit): "ai", "cloud", "digital_transformation", "data", "technology_consulting", "digital_experience", or "default" if none clearly fits.

## CRITICAL OUTPUT FORMAT
You MUST respond with ONLY a single valid JSON object. No markdown fences, no commentary, no text before or after. The exact format:
{"title":"<H1 / post title, includes primary keyword>","seo_title":"<50-60 char SEO title, starts with primary keyword, has a number + a power word>","slug":"<keyword-rich-url-slug>","meta_description":"<150-160 chars, primary keyword in first 120 chars>","content":"<full HTML>","image_prompt":"...","image_alt":"<short alt text that includes the primary keyword>","tags":["..."],"faq":[{"question":"...","answer":"..."}],"cta_category":"<ai|cloud|digital_transformation|data|technology_consulting|digital_experience|default>","ctas":[{"heading":"...","description":"...","button":"..."},{"heading":"...","description":"...","button":"..."},{"heading":"...","description":"...","button":"..."}]}`;
}

